// يحوّل رسالة الطالب (تليجرام أو صفحة الويب) لطلب موحّد
const j = $input.first().json;
const isTelegram = !!(j.message || j.update_id);
const toLatinDigits = s => String(s || '')
  .replace(/[٠-٩]/g, d => d.charCodeAt(0) - 0x0660)
  .replace(/[۰-۹]/g, d => d.charCodeAt(0) - 0x06F0);

const raw = isTelegram ? (j.message && j.message.text) || '' : (j.query && j.query.codes) || '';
let text = toLatinDigits(raw);
const upper = text.toUpperCase();

// الأكواد: EEN101 / een 101 / MEN499 I / AR334(1) / BS104M
const codeRe = /\b([A-Z]{2,4})[\s-]*(\d{3})([A-Z]{0,2})(\(\d\))?(?:\s+(I{1,2})(?![A-Z]))?(?:\s*[:=]\s*(\d{1,2}))?/g;
const codes = [], hours = {};
let rest = upper, m;
while ((m = codeRe.exec(upper))) {
  const code = m[1] + m[2] + (m[3] || '') + (m[4] || '') + (m[5] || '');
  if (!codes.includes(code)) codes.push(code);
  if (m[6] !== undefined) hours[code] = +m[6];
  rest = rest.replace(m[0], ' ');
}

// ساعات كل مادة وحدود التسجيل اللي الطالب كتبها
const query = j.query || {};
Object.keys(query).forEach(k => {
  if (/^h_/i.test(k) && /^\d{1,2}$/.test(toLatinDigits(query[k]).trim())) hours[k.slice(2).toUpperCase()] = +toLatinDigits(query[k]).trim();
});
const range = rest.match(/من\s*(\d{1,2})\s*(?:الى|إلى|لـ|ل|-)\s*(\d{1,2})/);
const asNum = v => /^\d{1,2}$/.test(toLatinDigits(v).trim()) ? +toLatinDigits(v).trim() : null;
const minHours = asNum(query.minHours) ?? (range ? +range[1] : null);
const maxHours = asNum(query.maxHours) ?? (range ? +range[2] : null);

// القسم: بالرمز أو بالعربي
let track = String((j.query && j.query.track) || '').toUpperCase().trim();
if (!track) {
  const t = rest.match(/(?:^|[^A-Z0-9/])(ME|TE|COM|CE|AR|P)(?![A-Z0-9])/);
  if (t) track = t[1];
  else {
    const ar = [[/ميكا/, 'ME'], [/اتصالات/, 'TE'], [/حاسب/, 'COM'], [/مدني/, 'CE'], [/عمار/, 'AR'], [/[اإ]عدادي/, 'P']];
    for (const [re, v] of ar) if (re.test(text)) { track = v; break; }
  }
}
if (!['ME', 'TE', 'COM', 'CE', 'AR', 'P'].includes(track)) track = '';

// روابط المشاركة تتحول لروابط تحميل مباشر
let url = String(j.sheetUrl || '').trim(), g;
if ((g = url.match(/docs\.google\.com\/spreadsheets\/d\/([\w-]+)/))) url = `https://docs.google.com/spreadsheets/d/${g[1]}/export?format=xlsx`;
else if ((g = url.match(/drive\.google\.com\/file\/d\/([\w-]+)/))) url = `https://drive.google.com/uc?export=download&id=${g[1]}`;
else if ((g = url.match(/github\.com\/([^/]+\/[^/]+)\/blob\/(.+)/))) url = `https://raw.githubusercontent.com/${g[1]}/${g[2]}`;

// رابط الفورم يتبني من العنوان اللي الطالب فاتح بيه، عشان يشتغل من الموبايل كمان
const hdr = j.headers || {}, host = hdr['x-forwarded-host'] || hdr.host;
let webhookUrl = j.webhookUrl || '';
const hook = webhookUrl.match(/^(https?):\/\/[^/]+(\/.*)$/);
if (host && hook) webhookUrl = `${String(hdr['x-forwarded-proto'] || hook[1]).split(',')[0].trim()}://${host}${hook[2]}`;

const command = /^\/(start|help)/i.test(text.trim()) ? 'help' : codes.length ? 'run' : isTelegram ? 'help' : 'landing';

return [{ json: {
  channel: isTelegram ? 'telegram' : 'web',
  chatId: isTelegram && j.message ? j.message.chat.id : null,
  messageId: isTelegram && j.message ? j.message.message_id : null,
  firstName: isTelegram && j.message && j.message.from ? j.message.from.first_name || '' : '',
  webhookUrl,
  rawText: String(raw).slice(0, 300),
  gibberish: isTelegram && !!raw && !codes.length && !raw.trim().startsWith('/'),
  codes: codes.slice(0, 12),
  tooMany: codes.length > 12,
  hours, minHours, maxHours,
  track, command,
  sheetSource: String(j.sheetSource || 'url').toLowerCase(),
  sheetUrl: url,
  sheetPath: j.sheetPath || '',
} }];

// ينضّف شيت الجامعة ويحوّله لكتالوج مواد منظم
const req = $('Parse Request').first().json;
const items = $input.all().map(i => i.json);
const compact = s => String(s == null ? '' : s).toLowerCase().replace(/[^a-z]/g, '');
const WANT = { day: 'day', timefrom: 'from', timeto: 'to', course: 'course', sectionno: 'secNo', sectionname: 'sec', teachingmethod: 'method', building: 'building', hall: 'hall', instructorname: 'instructor' };

// يدعم الحالتين: الهيدر متعرف عليه، أو لسه صف بيانات تحت عنوان الشيت
let rows = [];
const direct = items.length && Object.keys(items[0]).some(k => compact(k) === 'course');
if (direct) {
  rows = items.map(o => { const r = {}; for (const k in o) { const w = WANT[compact(k)]; if (w) r[w] = o[k]; } return r; });
} else {
  const hi = items.findIndex(o => { const v = Object.values(o).map(compact); return v.includes('course') && v.includes('day'); });
  if (hi >= 0) {
    const map = {};
    for (const k in items[hi]) { const w = WANT[compact(items[hi][k])]; if (w) map[k] = w; }
    rows = items.slice(hi + 1).map(o => { const r = {}; for (const k in o) if (map[k]) r[map[k]] = o[k]; return r; });
  }
}

const DAY = { saturday: 0, sunday: 1, monday: 2, tuesday: 3, wednesday: 4, thursday: 5, friday: 6 };
const KIND = { lec: 'LEC', tutorial: 'TUT', section: 'TUT', lab: 'LAB' };
function minutes(v) {
  if (v == null || v === '') return null;
  if (v instanceof Date) return v.getUTCHours() * 60 + v.getUTCMinutes() + (v.getUTCSeconds() >= 30 ? 1 : 0);
  if (typeof v === 'number' || /^\d*\.\d+$/.test(String(v).trim())) { const f = Number(v) % 1; return Math.round(f * 1440); }
  const s = String(v), m = s.match(/(\d{1,2}):(\d{2})(?::(\d{2}))?(?:\.\d+)?\s*(AM|PM)?/i);
  if (!m) return null;
  let h = +m[1]; const ap = (m[4] || '').toUpperCase();
  if (ap === 'PM' && h < 12) h += 12; if (ap === 'AM' && h === 12) h = 0;
  return h * 60 + +m[2] + (+(m[3] || 0) >= 30 ? 1 : 0);
}
const space = s => String(s == null ? '' : s).replace(/[‎‏]/g, '').replace(/\s+/g, ' ').trim();
function fixHall(v) {
  let s = space(v);
  [['tلي معمY حا~ب', 'معمل حاسب آلي'], ['tصO', 'فصل'], ['معمt', 'معمل'], ['018 tمعم', 'معمل 018'], ['tمعم', 'معمل'], ['01 ةϋاϗ', 'قاعة 01'], ['025 Νمدر', 'مدرج 025'],
   ['الحا~باΕ', 'الحاسبات'], ['ηبكاΕ', 'شبكات'], ['ال~ϥ', 'الألسن'], ['Pharma cology', 'Pharmacology'], ['Microbio logy', 'Microbiology'], ['Bioche mistry', 'Biochemistry']]
    .forEach(([a, b]) => { s = s.split(a).join(b); });
  return s.replace(/~/g, 'س').replace(/\s*-\s*([ab])$/, '-$1');
}
function fixBuilding(v) {
  const s = space(v).replace(/~/g, 'س').replace('Engineerin g', 'Engineering').replace(/مبني/g, 'مبنى');
  return s === 'مبنى كلية B الصيدلة' ? 'مبنى كلية الصيدلة B' : s;
}
function tracksOf(name) {
  const body = name.toUpperCase().replace(/^(LTN|LT|TUN|TU|LABN|LAB)/, '').replace(/\d+/g, ' ');
  return [...new Set(body.split(/[^A-Z]+/).filter(t => ['ME', 'TE', 'COM', 'CE', 'AR', 'P'].includes(t)))];
}

const courses = {}; let used = 0, skipped = 0;
for (const r of rows) {
  const day = DAY[compact(r.day)], start = minutes(r.from), end = minutes(r.to), kind = KIND[compact(r.method)];
  const parts = String(r.course || '').split('--');
  if (day === undefined || start == null || end == null || end <= start || !kind || parts.length < 2) { skipped++; continue; }
  const code = parts[0].replace(/\s+/g, '').toUpperCase(), name = space(parts.slice(1).join('--'));
  const c = courses[code] || (courses[code] = { code, name, activities: {} });
  const list = c.activities[kind] || (c.activities[kind] = []);
  const secName = space(r.sec) || `#${r.secNo}`;
  let sec = list.find(s => s.name === secName);
  if (!sec) { sec = { name: secName, tracks: tracksOf(secName), meetings: [], instructors: [] }; list.push(sec); }
  const hall = fixHall(r.hall), building = fixBuilding(r.building);
  if (!sec.meetings.some(x => x.day === day && x.start === start && x.end === end)) sec.meetings.push({ day, start, end, hall, building });
  const who = space(r.instructor);
  if (who && !sec.instructors.includes(who)) sec.instructors.push(who);
  used++;
}
const count = Object.keys(courses).length;
if (!count) return [{ json: { ...req, status: 'sheet_error', sheetDetail: 'الشيت اتقرا لكن مفيهوش الأعمدة المتوقعة (Day, Time From, Course ...).' } }];
return [{ json: { ...req, catalog: courses, sheetStats: { rows: used, skipped, courses: count } } }];

// لو الشيت ماتحمّلش، الطالب ياخد رد واضح بدل ما البوت يسكت
const req = $('Parse Request').first().json;
const e = $input.first().json.error;
const detail = typeof e === 'string' ? e : (e && e.message) || '';
return [{ json: { ...req, status: 'sheet_error', sheetDetail: detail.slice(0, 200) } }];

// يدوّر على الأكواد في الكتالوج ويحدد قسم الطالب والمجموعات المسموحة له
const r = $input.first().json;
if (r.status) return [{ json: r }];
const cat = r.catalog, all = Object.keys(cat);
const courseList = all.sort().map(c => ({ code: c, name: cat[c].name }));
const base = { ...r, courseList };
delete base.catalog;
if (r.command !== 'run') return [{ json: { ...base, status: r.command } }];

function lev(a, b) {
  const d = Array.from({ length: a.length + 1 }, (_, i) => [i]);
  for (let j = 1; j <= b.length; j++) d[0][j] = j;
  for (let i = 1; i <= a.length; i++) for (let j = 1; j <= b.length; j++)
    d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
  return d[a.length][b.length];
}
const found = [], unknown = [], hours = {};
const take = (c, q) => {
  if (!found.includes(c)) found.push(c);
  const h = r.hours[c] !== undefined ? r.hours[c] : r.hours[q];
  if (h !== undefined) hours[c] = h;
};
for (const q of r.codes) {
  if (cat[q]) { take(q, q); continue; }
  const pre = all.filter(c => c.startsWith(q));
  if (pre.length === 1) { take(pre[0], q); continue; }
  const near = pre.length ? pre : all.map(c => [c, lev(q, c)]).filter(x => x[1] <= 2).sort((a, b) => a[1] - b[1]).slice(0, 3).map(x => x[0]);
  unknown.push({ code: q, suggestions: near.map(c => ({ code: c, name: cat[c].name })) });
}
if (!found.length) return [{ json: { ...base, status: 'not_found', unknown } }];

// استنتاج القسم من المجموعات المكتوبة في أسماء السكاشن
const tally = {};
for (const c of found) {
  const ts = new Set();
  Object.values(cat[c].activities).forEach(l => l.forEach(s => s.tracks.forEach(t => ts.add(t))));
  ts.forEach(t => { tally[t] = (tally[t] || 0) + 1; });
}
const max = Math.max(0, ...Object.values(tally));
const top = Object.keys(tally).filter(t => tally[t] === max);
let track = r.track, trackSource = 'user';
if (!track && top.length === 1) { track = top[0]; trackSource = 'inferred'; }
const needTrack = !track && top.length > 1;
const { minHours: lo, maxHours: hi } = r;
const ask = error => [{ json: { ...base, status: 'need_hours', found, unknown, hours, track: track || '', trackOptions: needTrack ? top : [], hoursError: error || '' } }];
const hoursWord = n => n === 1 ? 'ساعة' : n === 2 ? 'ساعتين' : n <= 10 ? `${n} ساعات` : `${n} ساعة`;
const missing = found.filter(c => hours[c] === undefined);
if (missing.length || lo == null || hi == null) return ask();
if (lo > hi) return ask('الحد الأدنى لازم يكون أقل من الحد الأقصى أو يساويه.');
if (needTrack) return r.channel === 'web' ? ask('اختار قسمك عشان نحدد المجموعات المناسبة.') : [{ json: { ...base, status: 'need_track', found, unknown, hours, trackOptions: top } }];
const total = found.reduce((a, c) => a + hours[c], 0);
if (total < lo) return ask(`مجموع موادك ${hoursWord(total)}، والحد الأدنى ${hoursWord(lo)}. ناقصك ${hoursWord(lo - total)}، فضيف مادة أو راجع الساعات.`);
const sums = new Set([0]);
found.forEach(c => { [...sums].forEach(v => sums.add(v + hours[c])); });
if (![...sums].some(v => v >= lo && v <= hi)) return ask(`مفيش مجموعة من موادك مجموعها بين ${lo} و${hi} ساعة. راجع الساعات أو غيّر المواد.`);

const KL = { LEC: 'محاضرة', TUT: 'سكشن', LAB: 'معمل' }, notes = [], reqs = [], fallback = new Set();
for (const c of found) for (const kind of ['LEC', 'TUT', 'LAB']) {
  const secs = cat[c].activities[kind];
  if (!secs) continue;
  let open = track ? secs.filter(s => !s.tracks.length || s.tracks.includes(track)) : secs;
  if (!open.length) { open = secs; fallback.add(c); }
  reqs.push({ code: c, name: cat[c].name, kind, kindLabel: KL[kind], sections: open });
}
if (fallback.size) notes.push(`${[...fallback].join(' و ')}: مفيش مجموعات باسم قسم ${track} في بعض الأنشطة، فاتحسبت كل المجموعات المتاحة.`);
const byName = {};
found.forEach(c => { const k = cat[c].name.toLowerCase().replace(/[^a-z0-9]/g, ''); (byName[k] = byName[k] || []).push(c); });
Object.values(byName).filter(v => v.length > 1).forEach(v => notes.push(`${v.join(' و ')} هما نفس المادة بكودين مختلفين، غالبًا محتاج واحد بس منهم.`));
return [{ json: { ...base, status: 'ok', found, unknown, hours, track, trackSource, notes, reqs } }];

// يولّد كل الجداول الممكنة ويكشف التعارضات (بحث شامل مع قطع الفروع المتعارضة)
const r = $input.first().json;
if (r.status !== 'ok') return [{ json: r }];
const W = 3, D = 7, DW = D * W, BITS = 30, STEP = 10;
const pop = x => { x -= (x >>> 1) & 0x55555555; x = (x & 0x33333333) + ((x >>> 2) & 0x33333333); return (((x + (x >>> 4)) & 0x0F0F0F0F) * 0x01010101) >>> 24; };

// السكاشن اللي في نفس الميعاد بالظبط بتتجمع في اختيار واحد
let reqs = r.reqs.map(q => {
  const g = {};
  q.sections.forEach(s => {
    const k = s.meetings.map(m => `${m.day}|${m.start}|${m.end}`).sort().join(';');
    (g[k] = g[k] || { meetings: s.meetings, sections: [] }).sections.push(s);
  });
  return { ...q, options: Object.values(g) };
});
let base = Infinity;
reqs.forEach(q => q.options.forEach(o => o.meetings.forEach(m => { base = Math.min(base, m.start); })));
base = Math.floor(base / STEP) * STEP;
reqs.forEach(q => q.options.forEach(o => {
  o.mask = new Int32Array(DW);
  o.meetings.forEach(m => {
    const a = Math.floor((m.start - base) / STEP), b = Math.min(W * BITS, Math.ceil((m.end - base) / STEP));
    for (let i = a; i < b; i++) o.mask[m.day * W + Math.floor(i / BITS)] |= 1 << (i % BITS);
  });
}));
const clamp = x => Math.max(0, Math.min(100, x));

function metrics(occ, off) {
  let days = 0, gap = 0, total = 0, early = 0, late = 0, maxDay = 0, maxRun = 0, over = 0, heavy = 0, sumS = 0, sumE = 0, sig = 0;
  for (let d = 0; d < D; d++) {
    const p = off + d * W, a = occ[p], b = occ[p + 1], c = occ[p + 2];
    if (!(a | b | c)) continue;
    let first = -1, last = -1, n = 0, run = 0, best = 0;
    for (let i = 0; i < W * BITS; i++) {
      if (occ[p + Math.floor(i / BITS)] & (1 << (i % BITS))) { if (first < 0) first = i; last = i; n++; run++; if (run > best) best = run; } else run = 0;
    }
    const mins = n * STEP, s = base + first * STEP, e = base + (last + 1) * STEP;
    days++; sig |= 1 << d; total += mins; gap += (last - first + 1 - n) * STEP; sumS += s; sumE += e;
    if (s <= 540) early++; if (e >= 840) late++;
    if (mins > maxDay) maxDay = mins; if (best * STEP > maxRun) maxRun = best * STEP;
    over += Math.max(0, best * STEP - 200); heavy += Math.max(0, mins - 300);
  }
  const lb = Math.max(1, Math.ceil(total / 330));
  const sDays = clamp(100 - (days - lb) * 22), sGaps = clamp(100 - gap / 6), sComfort = clamp(100 - (over + heavy) / 2.5);
  const sTime = days ? clamp(100 - 60 * early / days - 40 * late / days) : 100;
  const score = sDays * .35 + sGaps * .30 + sComfort * .20 + sTime * .15;
  return { days, gap, total, early, late, maxDay, maxRun, avgStart: sumS / (days || 1), avgEnd: sumE / (days || 1), sig, sDays, sGaps, sComfort, sTime, score };
}

const KEYS = {
  best: m => -m.score,
  days: m => m.days * 1e6 + m.gap * 100 - m.score,
  gaps: m => m.gap * 1e4 + m.days * 1e3 - m.score,
  late: m => -m.avgStart * 1000 - m.score,
  finish: m => m.avgEnd * 1000 - m.score,
  light: m => m.maxDay * 1000 - m.score,
};
function search(list, opts) {
  const order = list.map((_, i) => i).sort((a, b) => list[a].options.length - list[b].options.length);
  const n = list.length, occ = new Int32Array((n + 1) * DW), pick = new Array(n).fill(0);
  const boards = {}; Object.keys(KEYS).forEach(k => { boards[k] = []; });
  const used = list.map(q => new Uint8Array(q.options.length));
  let valid = 0, nodes = 0, stop = false; const t0 = Date.now();
  (function go(depth) {
    if (stop) return;
    if (depth === n) {
      valid++;
      if (opts.count) return;
      for (let i = 0; i < n; i++) used[i][pick[i]] = 1;
      const m = metrics(occ, n * DW); let copy = null;
      for (const k in KEYS) {
        const b = boards[k], v = KEYS[k](m);
        if (b.length < 12 || v < b[b.length - 1].v) {
          copy = copy || pick.slice();
          let i = b.length; while (i > 0 && b[i - 1].v > v) i--;
          b.splice(i, 0, { v, c: copy, m }); if (b.length > 12) b.pop();
        }
      }
      return;
    }
    const idx = order[depth], o = list[idx].options, p = depth * DW, q = p + DW;
    for (let x = 0; x < o.length && !stop; x++) {
      if ((++nodes & 0xFFFF) === 0 && (nodes > opts.maxNodes || Date.now() - t0 > opts.maxMs)) { stop = true; return; }
      const mk = o[x].mask; let ok = true;
      for (let i = 0; i < DW; i++) { if (occ[p + i] & mk[i]) { ok = false; break; } occ[q + i] = occ[p + i] | mk[i]; }
      if (!ok) continue;
      pick[idx] = x; go(depth + 1);
    }
  })(0);
  return { valid, boards, used, truncated: stop, ms: Date.now() - t0 };
}

// لو المواد أكتر من الحد الأقصى: نختار أفضل مجموعة في حدود الساعات
const H = r.hours, lo = r.minHours, hi = r.maxHours, sumH = l => l.reduce((a, c) => a + H[c], 0);
const requested = r.found.slice(), totalH = sumH(requested);
let found = requested, triedSets = 0;
if (totalH > hi) {
  const sets = [];
  for (let b = 1; b < (1 << requested.length); b++) {
    const l = requested.filter((_, i) => b & (1 << i)), t = sumH(l);
    if (t >= lo && t <= hi) sets.push({ l, t });
  }
  sets.sort((a, b) => b.t - a.t || b.l.length - a.l.length);
  const t0 = Date.now(); let best = null;
  for (const x of sets) {
    if (best && x.t < best.t) break;
    if (Date.now() - t0 > 7000) break;
    triedSets++;
    const o = search(reqs.filter(q => x.l.includes(q.code)), { maxNodes: 2e6, maxMs: 500 });
    if (o.valid) { const sc = o.boards.best[0].m.score; if (!best || sc > best.sc) best = { ...x, sc }; }
  }
  found = (best || sets[0]).l;
  reqs = reqs.filter(q => found.includes(q.code));
}
const nameOf = c => (r.reqs.find(q => q.code === c) || {}).name || c;
const credit = { total: totalH, selected: sumH(found), min: lo, max: hi, triedSets,
  deferred: requested.filter(c => !found.includes(c)).map(c => ({ code: c, name: nameOf(c), hours: H[c] })) };

const possible = reqs.reduce((p, q) => p * q.options.length, 1);
const out = search(reqs, { maxNodes: 4e7, maxMs: 15000 });

// تحليل التعارضات بين كل زوج من الأنشطة
const fmtOverlap = (a, b) => {
  for (const x of a.meetings) for (const y of b.meetings)
    if (x.day === y.day && x.start < y.end && y.start < x.end) return { day: x.day, start: Math.max(x.start, y.start), end: Math.min(x.end, y.end) };
  return null;
};
const pairs = [];
for (let i = 0; i < reqs.length; i++) for (let j = i + 1; j < reqs.length; j++) {
